        {
            string Read(string suffix){using var stream=typeof(StandardClassicGeneralPackage).Assembly.GetManifestResourceStream("CardGame.Content.Standard.SkillPrograms.ol-dong-bai."+suffix)!;using var reader=new StreamReader(stream);return reader.ReadToEnd();}
            void Add(SkillProgramCatalog c){foreach(var(id,p)in c.Programs)b.AddSkill(new(id,c.Presentations[id].Name,c.Presentations[id].Description){Program=p,ProgramPresentation=c.Presentations[id],SelectionWeights=Enum.GetValues<Role>().ToDictionary(role=>role,_=>id==Quiet?10000d:-10000d)});}
            Add(SkillProgramCatalog.Load(Read("rules.json"),Read("presentation.json")));
            Add(SkillProgramCatalog.Load("""{"schemaVersion":62,"skills":[{"id":"fixture:dong-bai-driver","revision":1,"viewAs":[{"id":"human-response","inputKinds":["slash"],"inputSuits":[],"sourceZones":["hand"],"outputKind":"dodge","forPlay":false,"forResponse":true}],"activations":[{"id":"lose","minCards":0,"maxCards":0,"minTargets":1,"maxTargets":1,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"loseHp","target":"selectedTarget","amount":1}]},{"id":"equip-target","minCards":0,"maxCards":0,"minTargets":1,"maxTargets":1,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"useRandomDeckEquipment","target":"owner","resultBind":"equipment"}]},{"id":"obtain-equipment","minCards":0,"maxCards":0,"minTargets":1,"maxTargets":1,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"selectAndMoveOwnedCard","target":"owner","chooserRef":{"kind":"owner"},"cardOwnerRef":{"kind":"selectedTarget"},"zones":["equipment"],"count":1,"destination":"ownerHand","awaitMovementTriggers":true}]},{"id":"lose-self","minCards":0,"maxCards":0,"minTargets":1,"maxTargets":1,"targetKind":"anyLiving","usesPerTurn":null,"effects":[{"op":"loseHp","target":"selectedTarget","amount":1}]},{"id":"obtain","minCards":0,"maxCards":0,"minTargets":1,"maxTargets":1,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"selectAndMoveOwnedCard","target":"owner","chooserRef":{"kind":"owner"},"cardOwnerRef":{"kind":"selectedTarget"},"zones":["hand"],"count":1,"destination":"ownerHand","awaitMovementTriggers":true}]},{"id":"take","minCards":0,"maxCards":0,"minTargets":1,"maxTargets":1,"targetKind":"otherLiving","usesPerTurn":null,"effects":[{"op":"selectAndMoveOwnedCard","target":"owner","chooserRef":{"kind":"owner"},"cardOwnerRef":{"kind":"selectedTarget"},"zones":["hand"],"count":1,"destination":"discardPile","awaitMovementTriggers":true}]}]},{"id":"fixture:dong-bai-quiet","revision":1,"viewAs":[{"id":"slash-response","inputKinds":["slash"],"inputSuits":[],"sourceZones":["hand"],"outputKind":"dodge","forPlay":false,"forResponse":true}],"triggers":[{"id":"quiet","window":"afterNormalDraw","subject":"owner","optional":false,"effects":[{"op":"skipTurnPhases","target":"owner","phases":["play"]}]}]}]}""","""{"schemaVersion":3,"skills":{"fixture:dong-bai-driver":{"name":"真实驱动","description":"真实HP和卡移动"},"fixture:dong-bai-quiet":{"name":"静默","description":"跳过出牌"}}}"""));
            if(equipmentScene)b.AddCard(StandardContentRegistry.CreateWithClassicGenerals().GetCard("classic:silver-lion"));
            if(humanRecipient) Add(SkillProgramCatalog.Load("""{"schemaVersion":62,"skills":[{"id":"fixture:dong-bai-native-attacker","revision":1,"triggers":[{"id":"native","window":"afterNormalDraw","subject":"owner","optional":true,"usageScope":"game","usageLimit":1,"effects":[{"op":"selectTarget","target":"owner","targetKind":"otherLiving"},{"op":"useVirtualCard","target":"selectedTarget","outputKind":"slash","targetRestriction":"distanceUnlimitedAgainstTarget","useCardActionWindows":true}]}]}]}""","""{"schemaVersion":3,"skills":{"fixture:dong-bai-native-attacker":{"name":"真实杀驱动","description":"真人响应检查"}}}"""));
            if(clamp) Add(SkillProgramCatalog.Load("""{"schemaVersion":62,"skills":[{"id":"fixture:dong-bai-clamp","revision":1,"triggers":[{"id":"actual-clamp","window":"cardsGained","subject":"owner","destinationZones":["hand"],"movementReasons":["skill-program.lianzhu.GiftChildren"],"movementOccurrence":"perBatch","optional":true,"usageScope":"game","usageLimit":1,"effects":[{"op":"changeMaximumHp","target":"owner","amount":-1}]}]}]}""","""{"schemaVersion":3,"skills":{"fixture:dong-bai-clamp":{"name":"实际体力上限降低","description":"获得牌后真正钳制"}}}"""));
            if(paidWatch)
            {
                var rules="""{"schemaVersion":62,"skills":[{"id":"fixture:dong-bai-paid-watch","revision":1,"triggers":[{"id":"paid","window":"cardsMoved","subject":"owner","sourceZones":["hand"],"movementReasons":["skill-program.lianzhu.GiftChildren"],"movementOccurrence":"perBatch","optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"chooseOption","target":"owner","resultBind":"child","options":[{"id":"continue"}]},{"op":"loseHp","target":"owner","amount":20}]},{"id":"loss","window":"dyingEntering","subject":"owner","optional":false,"usageScope":"game","usageLimit":1,"effects":[{"op":"recover","target":"owner","amount":20},{"op":"loseOwnerSkillsAndGrant","target":"owner","sourceBind":"fixture:dong-bai-driver","skillIds":["ol:lianzhu","ol:xiahui","fixture:dong-bai-paid-watch"]}]}]}]}""";
                if(killOwner){var node=System.Text.Json.Nodes.JsonNode.Parse(rules)!; node["skills"]![0]!["triggers"]!.AsArray().RemoveAt(1); rules=node.ToJsonString();}
                Add(SkillProgramCatalog.Load(rules,"""{"schemaVersion":3,"skills":{"fixture:dong-bai-paid-watch":{"name":"真实已付赠牌子链","description":"原生濒死失源","optionLabels":{"continue":"继续"}}}}"""));
            }
            b.AddGeneral(new(Owner,"董白测试拥有者","supporter","ol:lianzhu","qun",4,paidWatch?["ol:xiahui",Driver,"fixture:dong-bai-paid-watch"]:["ol:xiahui",Driver],GeneralGender.Female));var peers=Enumerable.Range(1,3).Select(i=>"fixture:dong-bai-peer-"+i).ToArray();foreach(var p in peers)b.AddGeneral(new(p,"实际受赠角色","supporter",humanRecipient?"fixture:dong-bai-native-attacker":Quiet,"wei",4,humanRecipient?["ol:xiahui",Quiet]:clamp?["fixture:dong-bai-clamp"]:[],GeneralGender.Male));
            b.AddDeck(new("fixture:dong-bai-deck","固定四色实际杀",8,2,[]){PhysicalCards=Enumerable.Range(0,96).Select(i=>new ContentDeckPhysicalCard("standard:slash",i%2==0?Suit.Club:Suit.Heart,7)).Concat(equipmentScene?Enumerable.Range(0,32).Select(_=>new ContentDeckPhysicalCard("classic:silver-lion",Suit.Club,1)):[]).ToArray()});b.AddMode(new(Mode,"真实董白机制",4,4,new Dictionary<string,int>{{nameof(Role.Lord),1},{nameof(Role.Rebel),3}},"fixture:dong-bai-deck",GeneralCandidateCount:4,GeneralPoolIds:[Owner,..peers]));
        }
